import { AppAlgorithmEnv } from '..';

import { MouseEventData } from '../Model/AppCoreWrapper/IOWrapper/EventInteraction/MouseInteraction';

export class Implementation {
    app: AppAlgorithmEnv;

    // tslint:disable-next-line:no-any
    AlgorithmImplementation: any;
    // tslint:disable-next-line:no-any
    SceneVis: any;
    // tslint:disable-next-line:no-any
    SceneVisMapArchGIS: any;

    constructor(app: AppAlgorithmEnv) {
        this.app = app;
        this.InitAlgorithmImplementation();
        // this.InitSceneVis();
    }
    public InitPost() {
        //
    }
    async InitAlgorithmImplementation() {
        return import('./AlgorithmImplementation').then(({ AlgorithmImplementation }) => {
            this.AlgorithmImplementation = new AlgorithmImplementation(this);
            this.AlgorithmImplementation.InitPost();
        }).catch(err => {
            console.log('Stop loading NCanvas implementation, AlgorithmImplementation.'); console.log(err);
        });
    }
    AddMenu(app: string, subMenu: string, title: string, fn: () => void) {
        this.app.viewController.NUIWrapper.NUI.pullDownMenuWrapper.AddMenu(app, subMenu, title, fn);
    }
    // .............................................................................................................
    MouseEventController(e: MouseEventData) {
        if (this.AlgorithmImplementation) { this.AlgorithmImplementation.activeCommandController.MouseEventController(e); }
        // if (this.SceneVis) { this.SceneVis.activeCommandController.MouseEventController(e); }
    }
    Render(ctx: CanvasRenderingContext2D) {
        if (this.AlgorithmImplementation) { this.AlgorithmImplementation.Render(ctx); }
        // if (this.SceneVis) { this.SceneVis.Render(ctx); }
    }
    RemoveAllScene() {
        if (this.AlgorithmImplementation) { this.AlgorithmImplementation.Dispose(); } this.AlgorithmImplementation = undefined;
        // if (this.SceneVis) { this.SceneVis.Dispose(); } this.SceneVis = undefined;
    }
    ShiftScene(v: string) {
        this.RemoveAllScene();
        this.InitAlgorithmImplementation();

    }
    LoadDefinition(v0: string, v1: string) {
        // console.log(v0, v1);
        // if (v0 === 'creativeCoding') {
        //     if (this.SceneCreativeCoding) {
        //         console.log(this.SceneCreativeCoding);
        //         this.SceneCreativeCoding.LoadDefinition(v1);
        //     }
        // }
    }
}